let pySeeding = false;
function pyEnsureSeed(force) { if (pySeeding) return; const P = PYT(); if (!P) return; if (P.seedVer === PY_SEED_VER && !force) return; if (!HRT() || HRT().seedVer !== HR_SEED_VER) return; pySeeding = true; try { const fresh = pySeed(); const old = P || {}; ['structures', 'bank', 'loans'].forEach(k => Object.entries(old[k] || {}).forEach(([id, vv]) => { if (vv && vv.userMade) fresh[k][id] = vv; })); (old.runs || []).filter(r => r.userMade).forEach(r => { if (!fresh.runs.some(x => x.ym === r.ym)) fresh.runs.push(r); }); (old.fnf || []).forEach(f => fresh.fnf.push(f)); Store.put('payroll', fresh); PY_CACHE = {}; } catch (e) { console.error('Payroll seed failed', e); } finally { pySeeding = false; } }
