  ['cost', 'Staff cost by branch and department', ym => { const r = PYT().runs.find(x => x.ym === ym); if (!r) return { rows: [] }; const by = {}; pyLines(r).filter(l => !l.excluded && hrInBid(l.bid)).forEach(l => { const k = `${l.bid}|${l.dept}`; const o = by[k] = by[k] || { bid: l.bid, dept: l.dept, n: 0, gross: 0, er: 0 }; o.n++; o.gross += l.gross; o.er += l.pfEr + l.esiEr; }); return { cols: [{ h: 'Branch', k: o => hrBr(o.bid), t: 'text' }, { h: 'Department', k: o => o.dept, t: 'text' }, { h: 'Employees', k: o => o.n, t: 'num' }, { h: 'Gross', k: o => o.gross, t: 'inr' }, { h: 'Employer contributions', k: o => o.er, t: 'inr' }, { h: 'Total cost', k: o => o.gross + o.er, t: 'inr' }], rows: Object.values(by).sort((a, b) => b.gross - a.gross) }; }]
