PAGES.py_reports = { title: 'Payroll Reports', mod: 'py_reports', group: true, render() { const g = pyGuard(); if (g) return g; const ym = App.ui.pyYm || PYT().runs.filter(r => r.status === 'Paid').slice(-1).map(r => r.ym)[0] || PROC_TODAY.slice(0, 7); const key = PY_REPORTS.some(r => r[0] === App.ui.pyRep) ? App.ui.pyRep : 'register', def = PY_REPORTS.find(r => r[0] === key); let R; try { R = def[2](ym); } catch (e) { console.error(e); return `<div class="note bad">${esc(e.message)}</div>`; } const rows = R.rows || [], totalVals = rows.length && R.cols ? R.cols.map(c => c.t === 'inr' || (c.t === 'num' && !/days|employees/i.test(c.h)) ? rows.reduce((s, r) => { let x; try { x = c.x ? c.x(r) : c.k(r); } catch (e) { x = 0; } return s + (typeof x === 'number' && isFinite(x) ? x : 0); }, 0) : null) : null; const sel = `<label class="fld"><span>Report</span><select data-act="uiSel" data-k="pyRep">${PY_REPORTS.map(([k, l]) => `<option value="${k}" ${k === key ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label><label class="fld"><span>Month</span><select data-act="uiSel" data-k="pyYm">${PYT().runs.map(r => `<option value="${r.ym}" ${r.ym === ym ? 'selected' : ''}>${rmPeriodLabel(r.ym)} · ${r.status}</option>`).join('')}</select></label>`; return `${pyBar(sel)}${card(def[1], (R.html || '') + (R.cols ? table('pyRep', R.cols, rows, { totalVals, compact: true, title: def[1], limit: 200, empty: 'No data.' }) : ''), { right: exportBtns('pyRep', 'py_reports'), sub: 'Authorised Payroll / Finance users only · Excel / PDF / CSV download.' })}`; } };
/* ---------- actions ---------- */
const pySave = async P => { await Store.put('payroll', P); PY_CACHE = {}; };
const PY_ACT = {
  pyRunOpen: t => { const r = PYT().runs.find(x => x.id === t.dataset.k); if (r) { App.ui.pyYm = r.ym; go('py_run'); } },
  pyRunCreate: t => { const ym = t.dataset.k, prev = pcAddDays(ym + '-01', -1).slice(0, 7); const L = HRT().attLocks[prev]; if (ym <= PROC_TODAY.slice(0, 7) && !(HRT().attLocks[ym] && HRT().attLocks[ym].locked) && ym < PROC_TODAY.slice(0, 7)) return toast(`Attendance for ${rmPeriodLabel(ym)} must be locked by HR before payroll processing.`, 'bad'); askReason(`Create ${rmPeriodLabel(ym)} payroll`, 'Preview is computed from approved salary structures, locked attendance / approved leave, verified bank information and approved increments.', async r => { const P = Store.clone(PYT()); if (P.runs.some(x => x.ym === ym)) return; const chain = hrChain('Payroll').filter(x => x.role !== 'Payroll Executive'); const run = { id: 'RUN' + ym, no: pyNo(P, ym), ym, status: 'Draft', chain, level: 0, totals: null, excluded: {}, adjustments: {}, createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), locked: false, paidOn: '', bankFile: '', bankRef: '', jv: '', ver: 0, userMade: true, log: [] }; hrLog(run, 'Draft created – preview', r); P.runs.push(run); await pySave(P); audit('Payroll', 'Payroll run created', { new: run.no, reason: r }); App.ui.pyYm = ym; toast(`${run.no} created (preview).`); }); },
  pyRecalc: async t => { PY_CACHE = {}; const P = Store.clone(PYT()), r = P.runs.find(x => x.id === t.dataset.k); r.ver = (r.ver || 0) + 1; await pySave(P); toast('Recalculated from HR data.'); },
  pyLineDoc: t => { const [ym, emp] = t.dataset.k.split('|'); const r = PYT().runs.find(x => x.ym === ym); const l = pyLine(r, emp); if (!l) return; modal(`${l.emp} · ${esc(l.name)} · ${rmPeriodLabel(ym)}`, pyPayslipHtml(r, l), `<button class="btn" data-act="closeModal">Close</button><button class="btn" data-act="pyPayslip" data-k="${ym}|${emp}">Payslip PDF</button>${!r.locked && can('py_run', 'Edit') ? `<button class="btn" data-act="pyAdjForm" data-k="${r.id}|${emp}">Adjust</button>` : ''}`, true); },
  pyAdjForm: t => { const [id, emp] = t.dataset.k.split('|'); const r = PYT().runs.find(x => x.id === id); const E = pyEmployeesFor(r.ym); const a = (r.adjustments || {})[emp] || {}; modal('Payroll adjustment · ' + rmPeriodLabel(r.ym), `<div class="form-grid">${pcFld('Employee', `<select id="pa_emp">${E.slice(0, 600).map(e => `<option value="${e.id}" ${e.id === emp ? 'selected' : ''}>${esc(e.id)} · ${esc(e.name)}</option>`).join('')}</select>`)}${pcFld('Overtime (₹)', `<input id="pa_ot" type="number" value="${a.ot || 0}">`)}${pcFld('Arrears (₹)', `<input id="pa_arr" type="number" value="${a.arrears || 0}">`)}${pcFld('Incentive (₹)', `<input id="pa_inc" type="number" value="${a.incentive || 0}">`)}${pcFld('Reimbursement (approved, ₹)', `<input id="pa_reimb" type="number" value="${a.reimb || 0}">`)}${pcFld('Advance recovery (₹)', `<input id="pa_adv" type="number" value="${a.advance || 0}">`)}${pcFld('Approval reference (Finance flags incentive, arrears, reimbursement or advance without one)', `<input id="pa_ref" value="${esc(a.ref || '')}" placeholder="e.g. approval no. or memo">`)}${pcFld('Reason', '<input id="pa_reason">')}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="pyAdjOk" data-k="${r.id}">Save</button>`); },
  pyAdjOk: async t => { const reason = (v('pa_reason') || '').trim(); if (!reason) return toast('Reason is required.', 'bad'); const P = Store.clone(PYT()), r = P.runs.find(x => x.id === t.dataset.k); if (r.locked) return toast('Run is locked.', 'bad'); const emp = v('pa_emp'); r.adjustments = r.adjustments || {}; const old = JSON.stringify(r.adjustments[emp] || {}); r.adjustments[emp] = { ot: +v('pa_ot') || 0, arrears: +v('pa_arr') || 0, incentive: +v('pa_inc') || 0, reimb: +v('pa_reimb') || 0, advance: +v('pa_adv') || 0, ref: (v('pa_ref') || '').trim(), reason, by: App.user.name }; r.ver = (r.ver || 0) + 1; hrLog(r, 'Adjustment for ' + emp, reason); await pySave(P); audit('Payroll', 'Payroll adjustment', { old, new: JSON.stringify(r.adjustments[emp]), reason }); closeModal(); toast('Adjustment saved.'); },
  pyExclude: t => { const [id, emp, what] = t.dataset.k.split('|'); pcRemark(what === 'exclude' ? 'Exclude from this payroll' : 'Include in payroll', 'Reason is logged.', what === 'exclude', async rem => { const P = Store.clone(PYT()), r = P.runs.find(x => x.id === id); r.excluded = r.excluded || {}; if (what === 'exclude') r.excluded[emp] = rem; else delete r.excluded[emp]; r.ver = (r.ver || 0) + 1; hrLog(r, `${what === 'exclude' ? 'Excluded' : 'Included'} ${emp}`, rem); await pySave(P); audit('Payroll', what === 'exclude' ? 'Employee excluded from payroll' : 'Employee included in payroll', { new: emp, reason: rem }); closeModal(); }); },
  pyRunSubmit: t => { const r = PYT().runs.find(x => x.id === t.dataset.k); return PSD_ACT.psdCycleSubmit({ dataset: { k: r.ym } }); const lines = pyLines(r), tt = pyTotals(lines); askReason(`Submit ${r.no} for approval`, `${tt.n} employees · gross ${INR(tt.gross)} · net ${INR(tt.net)} · ${tt.held} on hold. Route: HR verification → Finance verification → CFO.`, async rr => { const P = Store.clone(PYT()), x = P.runs.find(y => y.id === r.id); x.status = 'Submitted'; x.level = 0; x.chain.forEach(L => Object.assign(L, { status: 'Pending', by: '', at: '', remark: '' })); x.totals = tt; x.createdBy = x.createdBy || App.user.id; hrLog(x, 'Submitted for approval', rr); await pySave(P); hrNotifyLevel(x, 'py_run'); audit('Payroll', 'Payroll submitted', { new: `${x.no} · net ${INR(tt.net)}`, reason: rr, approval: 'Submitted' }); closeModal(); toast(`${x.no} submitted – awaiting ${hrAwaiting(x)}.`); }); },
  pyRunDecide: t => { return toast('Payroll is now reconciled by Finance and approved by the CFO in Salary release.', 'bad'); const r = PYT().runs.find(x => x.id === t.dataset.k), a = t.dataset.v; if (!pyCanAct(r)) return toast('You are not the approver at this level, or you processed this run.', 'bad'); pcRemark(`${a} · ${r.no}`, `${r.chain[r.level].label} · net ${INR((r.totals || {}).net || 0)}`, a !== 'Approve', async rem => { const P = Store.clone(PYT()), x = P.runs.find(y => y.id === r.id); hrDecide(x, a, rem, d => { d.locked = true; d.lockedAt = nowIso(); }); await pySave(P); if (x.status === 'Submitted') hrNotifyLevel(x, 'py_run'); audit('Payroll', 'Payroll ' + a.toLowerCase(), { new: `${x.no} · ${x.status}`, reason: rem, approval: x.status, approver: App.user.name }); closeModal(); toast(`${x.no}: ${x.status}${x.locked ? ' (locked)' : ''}.`); }); },
  pyRunPay: t => { return toast('Salary is paid only through HR bank processing of CFO-approved batches (Salary release).', 'bad'); const r = PYT().runs.find(x => x.id === t.dataset.k); if ((Store.get('psd').batches || []).some(b => b.ym === r.ym && b.status !== 'Cancelled')) return toast('Salary for this month is being released in batches. Use Salary release to pay it.', 'bad'); const lines = pyLines(r).filter(l => !l.excluded), pay = lines.filter(l => !l.hold); askReason('Generate bank file, salary advice and post payroll JV', `${pay.length} employees · ${INR(pay.reduce((s, l) => s + l.net, 0))} via ${PYT().cfg.bankFileFormat}; ${lines.length - pay.length} held. The approved JV is posted to Finance.`, async rr => { const P = Store.clone(PYT()), x = P.runs.find(y => y.id === r.id); const tt = pyTotals(lines); x.status = 'Paid'; x.paidOn = PROC_TODAY; x.bankFile = `MSEA_SAL_${x.ym}_HDFC_ENET.xlsx`; x.bankRef = `PAYRUN-${x.ym}`; x.totals = tt; try { const ftx = Store.clone(FT()); const byBr = {}; lines.forEach(l => byBr[l.bid || ''] = (byBr[l.bid || ''] || 0) + l.gross); const L = [...Object.entries(byBr).map(([bid, gross]) => ({ gl: '5001', dr: gross, bid, cc: `CC-${bid || 'CORP'}-HR` })), { gl: '5002', dr: tt.pfEr, cc: 'CC-CORP-HR' }, { gl: '5003', dr: tt.esiEr, cc: 'CC-CORP-HR' }, { gl: '2104', cr: tt.net }, { gl: '2105', cr: tt.pf + tt.pfEr }, { gl: '2106', cr: tt.esi + tt.esiEr }, { gl: '2107', cr: tt.pt }, { gl: '2202', cr: tt.tds }, { gl: '1504', cr: tt.loan }].filter(l => (l.dr || 0) > 0 || (l.cr || 0) > 0); const j = fnJv(ftx, { date: fnPeriodOpen(PROC_TODAY) ? PROC_TODAY : PROC_TODAY, vtype: 'JV', type: 'Payroll', src: { mod: 'Payroll', kind: 'Approved payroll run', id: x.id, no: x.no, route: 'py_run' }, bid: '', cc: 'CC-CORP-HR', narration: `Payroll ${rmPeriodLabel(x.ym)} · ${tt.n} employees · ${x.no}`, lines: L, status: 'Posted', by: App.user.name }); x.jv = j.no; await Store.put('fin_tx', ftx); fnInvalidate(); } catch (e) { console.error(e); x.jv = x.jv || 'JV posting failed: ' + e.message; } hrLog(x, `Bank file ${x.bankFile} generated; salary advice issued; JV ${x.jv} posted`, rr); await pySave(P); if (window.XLSX) { try { const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Beneficiary Name', 'Account Number', 'IFSC', 'Amount', 'Mode', 'Narration'], ...pay.map(l => [l.name, l.acct, l.ifsc, l.net, l.net >= 200000 ? 'RTGS' : 'NEFT', `SAL ${x.ym} ${l.emp}`])]), 'Bulk'); await saveFile(x.bankFile, new Blob([XLSX.write(wb, { bookType: 'xlsx', type: 'array' })])); } catch (e) { } } audit('Payroll', 'Payroll paid – bank file & JV', { new: `${x.no} · ${x.bankFile} · ${x.jv}`, reason: rr, approval: 'Paid', approver: App.user.name }); closeModal(); toast(`${x.no} paid; JV ${x.jv} posted to Finance.`); }); },
  pyPayslip: async t => { const [ym, emp] = t.dataset.k.split('|'); const r = PYT().runs.find(x => x.ym === ym), l = pyLine(r, emp); if (!l) return; const me = hrEmpOfUser(); if (!(hrPayrollUser() || (me && me.id === emp))) return toast('Payslips are restricted.', 'bad'); if (!hrPayrollUser() && !psdPayslipOk(ym, emp)) return toast('Your payslip is released after the bank credits your salary.', 'bad'); audit('Payroll', 'Payslip downloaded', { new: `${emp} · ${ym}` }); if (window.jspdf) { try { const doc = new jspdf.jsPDF(); pdfLogo(doc); doc.setFontSize(13); doc.text(`Payslip – ${rmPeriodLabel(ym)}`, 20, 20); doc.setFontSize(9); doc.text(`MS Educational and Welfare Trust · ${l.emp} ${l.name} · ${l.desig} · ${hrBr(l.bid)} · paid days ${l.paid}/${l.cal}`, 20, 28, { maxWidth: 170 }); const rows = [['Basic', l.basic, 'PF', l.pf], ['HRA', l.hra, 'ESI', l.esi], ['Conveyance', l.conv, 'Professional tax', l.pt], ['Medical', l.med, 'TDS', l.tds], ['Special allowance', l.spl, 'Loan / advance', l.loan + l.adv], ['OT / arrears / incentive', l.ot + l.arrears + l.incentive, 'Reimbursement (+)', l.reimb], ['Gross', l.gross, 'Net pay', l.net]]; let y = 40; rows.forEach(rw => { doc.text(String(rw[0]), 20, y); doc.text(INR(rw[1]).replace('₹', 'Rs '), 80, y, { align: 'right' }); doc.text(String(rw[2]), 110, y); doc.text(INR(rw[3]).replace('₹', 'Rs '), 180, y, { align: 'right' }); y += 7; }); doc.text(`Bank: ${l.bank} XXXX${String(l.acct).slice(-4)} · ${r.status}`, 20, y + 6); await saveFile(`Payslip_${emp}_${ym}.pdf`, new Blob([doc.output('arraybuffer')], { type: 'application/pdf' })); } catch (e) { } } else toast('Payslip generated (demo).'); },
  pyPayslipsAll: t => { const r = PYT().runs.find(x => x.id === t.dataset.k); toast(`${pyLines(r).filter(l => !l.excluded).length} payslips generated and published to employee self-service (demo).`); audit('Payroll', 'Payslips published', { new: r.no }); },
  pySsForm: t => { const e = hrEmp(t.dataset.k), S = pyStructure(e.id); modal(`Salary structure · ${esc(e.name)} (${e.grade})`, `<div class="form-grid">${pcFld('Basic', `<input id="ss_basic" type="number" value="${S.basic}">`)}${pcFld('HRA', `<input id="ss_hra" type="number" value="${S.hra}">`)}${pcFld('Conveyance', `<input id="ss_conv" type="number" value="${S.conv}">`)}${pcFld('Medical', `<input id="ss_med" type="number" value="${S.med}">`)}${pcFld('Special allowance', `<input id="ss_spl" type="number" value="${S.spl}">`)}${pcFld('Effective from', `<input id="ss_from" type="date" value="${S.from || PROC_TODAY}">`)}${pcFld('Status', pcSel('ss_appr', ['Approved', 'Pending approval'], S.approved ? 'Approved' : 'Pending approval'))}</div><p class="small muted">Grade ${e.grade} range ${INR(hrGrade(e.grade).min)} – ${INR(hrGrade(e.grade).max)}. Approval by Finance Admin / CFO; the structure flows to payroll only when approved.</p>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="pySsOk" data-k="${e.id}">Save</button>`); },
  pySsOk: t => { const e = hrEmp(t.dataset.k); const s = { basic: +v('ss_basic') || 0, hra: +v('ss_hra') || 0, conv: +v('ss_conv') || 0, med: +v('ss_med') || 0, spl: +v('ss_spl') || 0 }; s.gross = s.basic + s.hra + s.conv + s.med + s.spl; const appr = v('ss_appr') === 'Approved'; if (appr && !/Finance Admin|CFO|System Admin|Super Admin/.test(App.user.role)) return toast('Only Finance Admin / CFO can approve a salary structure.', 'bad'); askReason('Save salary structure', `${e.name} · gross ${INR(s.gross)} · ${appr ? 'approved' : 'pending approval'}`, async r => { const P = Store.clone(PYT()); const old = JSON.stringify(pyStructure(e.id)); P.structures[e.id] = Object.assign(s, { approved: appr, ref: 'SS-' + e.id, from: v('ss_from'), by: App.user.name, at: nowIso(), userMade: true }); await pySave(P); const tx = Store.clone(HRT()); hrPatchEmp(tx, e.id, { ctc: s.gross, salaryRef: 'SS-' + e.id }); await hrSave(tx); audit('Payroll', 'Salary structure ' + (appr ? 'approved' : 'saved'), { old, new: JSON.stringify(s), reason: r, approval: appr ? 'Approved' : 'Pending', approver: App.user.name }); closeModal(); toast('Saved.'); }); },
  pyBankForm: t => { const e = hrEmp(t.dataset.k), B = pyBankOf(e.id); modal(`Bank details · ${esc(e.name)}`, `<div class="form-grid">${pcFld('Account holder', `<input id="bk_holder" value="${esc(B.holder || e.name)}">`)}${pcFld('Bank', `<input id="bk_bank" value="${esc(B.bank)}">`)}${pcFld('Account number', `<input id="bk_acct" value="${esc(B.acct)}">`)}${pcFld('IFSC', `<input id="bk_ifsc" value="${esc(B.ifsc)}">`)}${pcFld('Bank branch', `<input id="bk_branch" value="${esc(B.branch)}">`)}${pcFld('Account type', pcSel('bk_type', ['Savings', 'Salary', 'Current'], B.type || 'Salary'))}${pcFld('Proof (cancelled cheque / bank proof)', `<input id="bk_proof" type="file">${B.proof ? `<span class="small">${esc(B.proof)}</span>` : ''}`)}${pcFld('Verification', pcSel('bk_ver', ['Verified', 'Unverified'], B.verified ? 'Verified' : 'Unverified'))}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="pyBankOk" data-k="${e.id}">Save</button>`); },
  pyBankOk: t => { const e = hrEmp(t.dataset.k); { const lk = (PYT().runs || []).find(r => PSD_LOCKED.includes(psdCs(r.ym)) && pyLines(r).some(l => l.emp === e.id && !l.excluded)); if (lk) return toast(`Bank details cannot be changed while the ${psdMonth(lk.ym)} payroll is locked. Raise a Payroll Revision Request.`, 'bad'); } const acct = (v('bk_acct') || '').trim(), ifsc = (v('bk_ifsc') || '').trim().toUpperCase(); if (!/^\d{9,18}$/.test(acct) || !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(ifsc)) return toast('Valid account number (9–18 digits) and IFSC required.', 'bad'); const f = document.getElementById('bk_proof'); const ver = v('bk_ver') === 'Verified'; if (ver && !(f && f.files[0]) && !pyBankOf(e.id).proof) return toast('Bank proof must be uploaded before verification.', 'bad'); const locked = PYT().runs.some(r => r.ym === PROC_TODAY.slice(0, 7) && r.locked); askReason('Save bank details', `${e.name} · ${v('bk_bank')} XXXX${acct.slice(-4)}${locked ? ' · payroll is locked – Finance / Payroll approval recorded' : ''}`, async r => { const P = Store.clone(PYT()); const old = pyBankOf(e.id); P.bank[e.id] = { holder: v('bk_holder'), bank: v('bk_bank'), acct, ifsc, branch: v('bk_branch'), type: v('bk_type'), proof: f && f.files[0] ? f.files[0].name : old.proof, verified: ver, verifiedBy: ver ? App.user.name : '', at: ver ? nowIso() : '', userMade: true }; await pySave(P); audit('Payroll', 'Staff bank details ' + (ver ? 'verified' : 'updated'), { old: `${old.bank} XXXX${String(old.acct).slice(-4)}`, new: `${v('bk_bank')} XXXX${acct.slice(-4)}`, reason: r, approval: ver ? 'Verified' : 'Unverified', approver: App.user.name }); closeModal(); toast('Saved.'); }); },
  pyBankReqDecide: t => { const r = HRT().bankReq.find(x => x.id === t.dataset.k), a = t.dataset.v; if (!hrCanAct(r)) return toast('You are not the approver at this level.', 'bad'); pcRemark(`${a} · ${r.no}`, `${(hrEmp(r.emp) || {}).name} · ${r.new.bank} XXXX${String(r.new.acct).slice(-4)} · proof ${r.new.proof}`, a !== 'Approve', async rem => { const tx = Store.clone(HRT()), x = tx.bankReq.find(y => y.id === r.id); let applied = false; hrDecide(x, a, rem, async d => { applied = true; }); await hrSave(tx); if (applied) { const P = Store.clone(PYT()); P.bank[x.emp] = Object.assign({}, x.new, { verified: true, verifiedBy: App.user.name, at: nowIso(), userMade: true }); await pySave(P); } else if (x.status === 'Submitted') hrNotifyLevel(x, 'py_bank'); audit('Payroll', 'Bank-detail change ' + a.toLowerCase(), { old: `${x.old.bank} XXXX${String(x.old.acct).slice(-4)}`, new: `${x.new.bank} XXXX${String(x.new.acct).slice(-4)}`, reason: rem, approval: x.status, approver: App.user.name }); closeModal(); toast(`${x.no}: ${x.status}.`); }); },
  pyLoanForm: () => modal('Loan / salary advance', `<div class="form-grid">${pcFld('Employee', `<select id="ln_emp">${hrEmps().filter(hrActive).slice(0, 600).map(e => `<option value="${e.id}">${esc(e.id)} · ${esc(e.name)}</option>`).join('')}</select>`)}${pcFld('Kind', pcSel('ln_kind', ['Salary advance', 'Festival advance', 'Loan'], 'Salary advance'))}${pcFld('Amount', '<input id="ln_amt" type="number" value="20000">')}${pcFld('EMI', '<input id="ln_emi" type="number" value="5000">')}</div>`, '<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="pyLoanOk">Save</button>'),
  pyLoanOk: async () => { const P = Store.clone(PYT()); P.loans[v('ln_emp')] = { kind: v('ln_kind'), amount: +v('ln_amt') || 0, emi: +v('ln_emi') || 0, balance: +v('ln_amt') || 0, from: PROC_TODAY, userMade: true }; await pySave(P); audit('Payroll', 'Loan / advance recorded', { new: `${v('ln_emp')} · ${INR(+v('ln_amt'))}` }); closeModal(); toast('Saved.'); },
  pyFnfDone: t => askReason('Full & final settlement', 'Settles pending salary, leave encashment, notice recovery and deductions; posted with the next payroll JV.', async r => { const P = Store.clone(PYT()), f = P.fnf.find(x => x.id === t.dataset.k); f.status = 'Settled'; f.settledAt = nowIso(); f.by = App.user.name; await pySave(P); const tx = Store.clone(HRT()), x = tx.exits.find(y => y.id === f.exit); if (x) { x.fnf = 'Settled'; hrLog(x, 'F&F settled by payroll', r); await hrSave(tx); } audit('Payroll', 'F&F settled', { new: f.emp, reason: r, approver: App.user.name }); closeModal(); toast('Settled.'); })
};
function pyPayslipHtml(r, l) { return `<div class="payslip"><img src="data:image/png;base64,${LOGO_B64}" alt="MS Education Academy" style="height:40px;margin-bottom:6px"><h3>Payslip · ${rmPeriodLabel(r.ym)} · ${hrPill(r.status)}</h3><p class="small">${l.emp} · ${esc(l.name)} · ${esc(l.desig)} · ${esc(hrBr(l.bid))} · ${l.dept} · paid days ${l.paid} / ${l.cal} · LOP ${l.lop}</p><div class="grid2"><div>${table('pyEarn', [{ h: 'Earnings', k: x => x[0], t: 'text' }, { h: 'Amount', k: x => x[1], t: 'inr' }], [['Basic', l.basic], ['HRA', l.hra], ['Conveyance', l.conv], ['Medical', l.med], ['Special allowance', l.spl], ['Overtime', l.ot], ['Arrears', l.arrears], ['Incentive', l.incentive], ['Reimbursement', l.reimb]], { compact: true, totalVals: [null, l.gross + l.reimb] })}</div><div>${table('pyDed', [{ h: 'Deductions', k: x => x[0], t: 'text' }, { h: 'Amount', k: x => x[1], t: 'inr' }], [['Provident fund', l.pf], ['ESI', l.esi], ['Professional tax', l.pt], ['TDS', l.tds], ['Loan / advance', l.loan + l.adv]], { compact: true, totalVals: [null, l.ded] })}<p><b>Net pay ${INR(l.net)}</b> · ${l.bank} XXXX${String(l.acct).slice(-4)} · ${l.hold ? '<span class="red">' + esc(l.hold) + '</span>' : 'bank verified'}</p></div></div></div>`; }
